# -*- coding: utf-8 -*-
# Nikolsky 11, exercises 4.7–4.8: derivative + seven values + three equations in one answer, and «Выполните задание 4.7…»
# references. Each becomes single questions (derivative; value at x = 2; x where f'(x) = 3).
SPLIT = {}
def P(q, k, d, yn=False): return {"q": q, "k": k, "d": d, "yesno": yn}
def T(parent, why, parts): SPLIT[parent] = {"why": why, "parts": parts}
WHY = "в одной задаче с выбором ответа были производная, семь её значений и три уравнения (ответ угадывался сравнением вариантов), условие ссылалось на «задание 4.7», которого ученик не видит"

def fam(parent, f, fp, fp2, x3, d1, d2, d3):
    T(parent, WHY, [
        P(r"Найдите производную функции $f(x)=%s$ в любой точке $x$." % f, r"$f'(x)=%s$" % fp, d1),
        P(r"Найдите значение производной функции $f(x)=%s$ в точке $x=2$." % f, r"$%s$" % fp2, d2),
        P(r"При каком значении $x$ производная функции $f(x)=%s$ равна $3$?" % f, x3, d3)])

fam("G11_TB_4_2_4_8_1", "3x+8", "3", "3", r"при любом $x$",
    [(r"$f'(x)=3x$", r"Ученик оставил переменную: производная $kx$ равна $k$, а не $kx$."), (r"$f'(x)=8$", r"Ученик продифференцировал только свободный член; производная постоянной равна $0$, а $(3x)'=3$."), (r"$f'(x)=11$", r"Ученик сложил коэффициенты $3+8$; производная линейной функции равна угловому коэффициенту $3$.")],
    [(r"$14$", r"Ученик вычислил значение функции $f(2)=3\cdot2+8$, а не производной."), (r"$6$", r"Ученик умножил производную на $x$: $3\cdot2$; производная $f'(x)=3$ от $x$ не зависит."), (r"$0$", r"Ученик решил, что производная постоянной функции равна нулю; но $f(x)=3x+8$ не постоянна, $f'(x)=3$.")],
    [(r"ни при каком $x$", r"Ученик перепутал с функцией $8x-11$; здесь $f'(x)=3$ при всех $x$."), (r"при $x=1$", r"Ученик решил уравнение $3x=3$; но производная равна $3$ при любом $x$, от $x$ она не зависит."), (r"при $x=-\dfrac{5}{3}$", r"Ученик решил уравнение $3x+8=3$ для самой функции, а не для производной.")])
fam("G11_TB_4_2_4_8_2", "8x-11", "8", "8", r"ни при каком $x$",
    [(r"$f'(x)=8x$", r"Ученик оставил переменную: производная $kx$ равна $k$."), (r"$f'(x)=-11$", r"Ученик продифференцировал только свободный член; производная постоянной равна $0$."), (r"$f'(x)=-3$", r"Ученик сложил коэффициенты $8-11$; производная линейной функции равна $8$.")],
    [(r"$5$", r"Ученик вычислил значение функции $f(2)=16-11$, а не производной."), (r"$16$", r"Ученик умножил производную на $x$: $8\cdot2$; производная $f'(x)=8$ от $x$ не зависит."), (r"$0$", r"Ученик решил, что производная равна нулю; но $f'(x)=8$.")],
    [(r"при любом $x$", r"Ученик перепутал с функцией $3x+8$; здесь $f'(x)=8\ne3$ при всех $x$."), (r"при $x=\dfrac{3}{8}$", r"Ученик решил уравнение $8x=3$; но производная равна $8$ при любом $x$."), (r"при $x=\dfrac{7}{4}$", r"Ученик решил уравнение $8x-11=3$ для самой функции, а не для производной.")])
fam("G11_TB_4_2_4_8_3", "kx+b", "k", "k", r"при $k=3$ — при любом $x$; при $k\ne3$ — ни при каком $x$",
    [(r"$f'(x)=kx$", r"Ученик оставил переменную: производная $kx$ равна $k$."), (r"$f'(x)=b$", r"Ученик продифференцировал только свободный член; производная постоянной равна $0$."), (r"$f'(x)=k+b$", r"Ученик сложил коэффициенты; производная линейной функции равна $k$.")],
    [(r"$2k+b$", r"Ученик вычислил значение функции $f(2)$, а не производной."), (r"$2k$", r"Ученик умножил производную на $x$; производная $f'(x)=k$ от $x$ не зависит."), (r"$0$", r"Ученик решил, что производная равна нулю; но $f'(x)=k$.")],
    [(r"при $x=\dfrac{3}{k}$", r"Ученик решил уравнение $kx=3$; но производная равна $k$ при любом $x$, поэтому ответ зависит только от $k$."), (r"при $x=\dfrac{3-b}{k}$", r"Ученик решил уравнение $kx+b=3$ для самой функции, а не для производной."), (r"при любом $x$", r"Ученик не учёл, что при $k\ne3$ производная не равна $3$ ни в одной точке.")])
fam("G11_TB_4_2_4_8_4", "x^{2}-x+5", "2x-1", "3", r"при $x=2$",
    [(r"$f'(x)=2x-1+5$", r"Ученик не обнулил производную постоянной: $(5)'=0$."), (r"$f'(x)=x^{2}-1$", r"Ученик продифференцировал только слагаемое $-x$; $(x^{2})'=2x$."), (r"$f'(x)=2x+1$", r"Ученик ошибся в знаке: $(-x)'=-1$.")],
    [(r"$7$", r"Ученик вычислил значение функции $f(2)=4-2+5$, а не производной $f'(2)=2\cdot2-1$."), (r"$5$", r"Ученик взял $f'(x)=2x+1$ с неверным знаком; верно $f'(2)=3$."), (r"$4$", r"Ученик нашёл только $(x^{2})'=2x$ при $x=2$ и забыл слагаемое $-1$.")],
    [(r"при $x=1$", r"Ученик решил уравнение $2x=3-1$; верно $2x-1=3$, $x=2$."), (r"при $x=\dfrac{3}{2}$", r"Ученик потерял слагаемое $-1$ и решил $2x=3$."), (r"при $x=-1$ и $x=2$", r"Ученик решил уравнение $x^{2}-x+5=7$ для функции, а не для производной.")])
fam("G11_TB_4_2_4_8_5", "x^{2}+3x-1", "2x+3", "7", r"при $x=0$",
    [(r"$f'(x)=2x+3-1$", r"Ученик не обнулил производную постоянной: $(-1)'=0$."), (r"$f'(x)=x^{2}+3$", r"Ученик продифференцировал только слагаемое $3x$; $(x^{2})'=2x$."), (r"$f'(x)=2x-3$", r"Ученик ошибся в знаке: $(3x)'=3$.")],
    [(r"$9$", r"Ученик вычислил значение функции $f(2)=4+6-1$, а не производной $f'(2)=2\cdot2+3$."), (r"$4$", r"Ученик нашёл только $(x^{2})'=2x$ при $x=2$ и забыл слагаемое $3$."), (r"$1$", r"Ученик взял $f'(x)=2x-3$ с неверным знаком; верно $f'(2)=7$.")],
    [(r"при $x=3$", r"Ученик решил уравнение $2x-3=3$ с неверным знаком производной; верно $2x+3=3$, $x=0$."), (r"при $x=\dfrac{3}{2}$", r"Ученик потерял слагаемое $3$ и решил $2x=3$."), (r"ни при каком $x$", r"Ученик не заметил, что $2x+3=3$ при $x=0$.")])
fam("G11_TB_4_2_4_8_6", "ax^{2}+bx+c", "2ax+b", "4a+b", r"при $x=\dfrac{3-b}{2a}$ ($a\ne0$)",
    [(r"$f'(x)=2ax+b+c$", r"Ученик не обнулил производную постоянной: $c'=0$."), (r"$f'(x)=ax+b$", r"Ученик забыл множитель $2$: $(ax^{2})'=2ax$."), (r"$f'(x)=2ax$", r"Ученик потерял производную слагаемого $bx$, равную $b$.")],
    [(r"$4a+2b+c$", r"Ученик вычислил значение функции $f(2)$, а не производной."), (r"$2a+b$", r"Ученик подставил $x=1$ вместо $x=2$."), (r"$4a$", r"Ученик потерял слагаемое $b$: $f'(2)=2a\cdot2+b$.")],
    [(r"при $x=\dfrac{3}{2a}$", r"Ученик потерял слагаемое $b$ и решил $2ax=3$."), (r"при $x=\dfrac{3+b}{2a}$", r"Ученик ошибся в знаке при переносе $b$: из $2ax+b=3$ получается $x=\dfrac{3-b}{2a}$."), (r"при $x=\dfrac{3-b}{a}$", r"Ученик забыл множитель $2$ в производной $(ax^{2})'=2ax$.")])

T("G11_TB_4_2_4_7_2", "семь значений производной в одной задаче с выбором ответа: ответ угадывался сравнением вариантов; оставлены три характерные точки", [
 P(r"Дана функция $f(x)=x^{2}$. Найдите значение её производной в точке $x=1$.", r"$2$", [(r"$1$", r"Ученик вычислил значение функции $f(1)=1$, а не производной $f'(1)=2\cdot1$."), (r"$0$", r"Ученик решил, что производная $x^{2}$ равна $0$; $(x^{2})'=2x$."), (r"$3$", r"Ученик применил формулу $(x^{n})'=nx^{n+1}$; верно $(x^{2})'=2x$.")]),
 P(r"Дана функция $f(x)=x^{2}$. Найдите значение её производной в точке $x=-2$.", r"$-4$", [(r"$4$", r"Ученик потерял знак: $f'(-2)=2\cdot(-2)=-4$; значение $4$ — это $f(-2)$."), (r"$-2$", r"Ученик не умножил на $2$: $(x^{2})'=2x$."), (r"$-1$", r"Ученик разделил на $2$ вместо умножения: $f'(-2)=2\cdot(-2)=-4$.")]),
 P(r"Дана функция $f(x)=x^{2}$. Найдите значение её производной в точке $x=3$.", r"$6$", [(r"$9$", r"Ученик вычислил значение функции $f(3)=9$, а не производной."), (r"$3$", r"Ученик не умножил на $2$: $(x^{2})'=2x$."), (r"$27$", r"Ученик применил формулу $(x^{n})'=nx^{n+1}$: $3^{3}$; верно $2\cdot3=6$.")]),
])
T("G11_TB_4_2_4_7_3", "три уравнения в одной задаче с выбором ответа: ответ угадывался сравнением вариантов", [
 P(r"Дана функция $f(x)=x^{2}$. При каком значении $x$ её производная равна $0$?", r"$x=0$", [(r"$x=1$", r"Ученик решил уравнение $x^{2}=1$; производная $f'(x)=2x$ равна нулю при $x=0$."), (r"ни при каком $x$", r"Ученик не заметил, что $2x=0$ при $x=0$."), (r"$x=2$", r"Ученик подставил показатель степени вместо решения $2x=0$.")]),
 P(r"Дана функция $f(x)=x^{2}$. При каком значении $x$ её производная равна $1$?", r"$x=\dfrac{1}{2}$", [(r"$x=1$", r"Ученик решил $x^{2}=1$ для функции, а не $2x=1$ для производной."), (r"$x=2$", r"Ученик умножил вместо деления: из $2x=1$ следует $x=\dfrac{1}{2}$."), (r"$x=\pm1$", r"Ученик решил $x^{2}=1$ для функции, а не $2x=1$ для производной.")]),
 P(r"Дана функция $f(x)=x^{2}$. При каком значении $x$ её производная равна $3$?", r"$x=\dfrac{3}{2}$", [(r"$x=\sqrt{3}$", r"Ученик решил $x^{2}=3$ для функции, а не $2x=3$ для производной."), (r"$x=6$", r"Ученик умножил вместо деления: из $2x=3$ следует $x=\dfrac{3}{2}$."), (r"$x=3$", r"Ученик не учёл множитель $2$ в производной $(x^{2})'=2x$.")]),
])
